package codeshape

import (
	"bytes"
	"reflect"
	"testing"
)

func TestRender(t *testing.T) {
	allow := Allowlist{
		Files: map[string]Entry{
			"z.go": {Value: 501, Reason: "split by concern"},
			"a.go": {Value: 502, Reason: "generated by codegen"},
		},
		Dirs:    map[string]Entry{"pkg": {Value: 11, Reason: "split package tests"}},
		Present: false,
	}
	first := Render(allow)
	second := Render(allow)
	if !bytes.Equal(first, second) {
		t.Fatalf("Render changed between calls: %q != %q", first, second)
	}
	want := []byte(
		"files: {\n\t\"a.go\": {value: 502, reason: \"generated by codegen\"},\n" +
			"\t\"z.go\": {value: 501, reason: \"split by concern\"},\n}\n" +
			"dirs: {\n\t\"pkg\": {value: 11, reason: \"split package tests\"},\n}\n",
	)
	if !bytes.Equal(first, want) {
		t.Fatalf("Render = %q, want %q", first, want)
	}
}

func TestRenderRoundTrip(t *testing.T) {
	allow := Allowlist{
		Files: map[string]Entry{
			`large"file.go`: {Value: 501, Reason: `split "quoted" concern`},
		},
		Dirs:    map[string]Entry{"pkg": {Value: 11, Reason: "split package tests"}},
		Present: false,
	}
	root := newFixtureRepo(t)
	writeConfigFiles(t, root, validConfig, string(Render(allow)))
	_, got, err := Load(root)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got.Files, allow.Files) || !reflect.DeepEqual(got.Dirs, allow.Dirs) {
		t.Fatalf("Load after Render = files %#v, dirs %#v; want files %#v, dirs %#v",
			got.Files, got.Dirs, allow.Files, allow.Dirs)
	}
}
